var APP="Dark/Clean";var ID="conversation--menu";
var IDS=['signin','home','conversation','conversation--approval','conversation--menu','conversation--delete','search','activity','activity--work'];
var PAGE='Proto iOS '+APP.split('/')[0];
function txt(p,t,size,role,w){return H.text({parent:p,text:t,size:size||14,weight:size>=20?7:5,color:H.sw(APP,role||'ink'),w:w||326})}
function col(p,n,w,pad,gap,fill){var f=H.frame({parent:p,name:n,dir:'col',w:w||358,pad:pad||0,gap:gap===undefined?12:gap,fill:fill?H.sw(APP,fill):null,radius:16});f.stackLayout.alignItems=sketch.StackLayout.AlignItems.Start;return f}
function btn(p,t,id,kind,w){var f=H.frame({parent:p,name:'link:'+id,w:w||326,h:48,pad:12,radius:12,fill:H.sw(APP,kind==='primary'?'accent':kind==='danger'?'danger':'surface'),border:kind?'':H.sw(APP,'line'),justify:sketch.StackLayout.JustifyContent.Center});H.text({parent:f,text:t,size:15,weight:6,color:kind?'#ffffff':H.sw(APP,'ink')});H.order(f);return f}
function row(p,t,sub,id,status){var f=col(p,'link:'+id,358,16,8,'surface');f.style.borders=[{color:H.sw(APP,'line'),thickness:1,position:sketch.Style.BorderPosition.Inside}];if(status)txt(f,status,11,'accent',326);txt(f,t,16,'ink',326);if(sub)txt(f,sub,12,'secondary',326);H.order(f);return f}
function gapfill(p){var f=col(p,'flex-space',358,0,0);f.verticalSizing=sketch.FlexSizing.Fill;return f}
function composer(p){var wrap=col(p,'composer-dock',358,0,0);var i=H.inst('Composer/'+APP+'/phone-docked',wrap);i.frame.width=358;i.overrides.filter(function(o){return o.property==='stringValue'&&String(o.value).indexOf('Message Harso')>=0}).forEach(function(o){o.value='Message Weave…'});H.link(i,'conversation');H.order(wrap);return wrap}
function findScreen(){return H.page(PAGE).layers.find(function(l){return l.name==='Screen/ios/'+APP+'/'+ID})}
function close(s,b){H.order(b);H.relayout(s);s.frame.width=390;s.frame.height=844;s.frame.x=IDS.indexOf(ID)*510;s.frame.y=0;H.out({id:ID,app:APP,frame:s.id,w:s.frame.width,h:s.frame.height});}
function thread(b){txt(b,'PERSONAL',11,'tertiary');txt(b,'Move the billing webhook handler onto the new ledger client',22);var u=col(b,'user-message',358,16,0,'hover');txt(u,'Run only the webhook tests first.',14);H.order(u);var a=col(b,'assistant-message',358,0,10);H.icon({parent:a,d:H.paths.sparkles,size:22,color:H.hex(APP,'accent')});txt(a,"Running only services/billing/webhook.test.ts. I’ll ask before executing anything.",14);H.order(a);row(b,'terminal','Awaiting permission to run the test command.','conversation--approval','APPROVAL REQUIRED');row(b,'Prepare the release','Release checks · Verify the candidate · 1 / 3','activity--work','● RUNNING');gapfill(b);composer(b)}

var titles={signin:undefined,home:'Weave',conversation:'Conversation',search:'Search',activity:'Activity','activity--work':'Work details'};var base=ID.indexOf('conversation--')===0?'conversation':ID;var o=H.iosScreen({page:PAGE,app:APP,id:ID,x:IDS.indexOf(ID)*510,y:0,title:titles[base],back:base==='conversation'||ID==='activity--work',trailing:base==='conversation'?'dots':ID==='home'||ID==='activity'?'search':undefined,trailingLink:base==='conversation'?'conversation--menu':'search',tab:ID==='home'?'home':ID==='activity'?'activity':false});o.body.stackLayout.alignItems=sketch.StackLayout.AlignItems.Start;o.finish();var caption=H.text({parent:H.page(PAGE),text:ID,size:13,color:H.sw(APP,'tertiary'),name:'caption:'+ID});caption.frame.x=IDS.indexOf(ID)*510;caption.frame.y=-28;H.out({app:APP,id:ID,frame:o.screen.id});